import json, re, sys
data = json.load(sys.stdin)

# Combine all tables with Calendar year 1995 to find max
all_countries = {}

# Find all tables with Calendar year 1995
for elem in data.get('document', {}).get('elements', []):
    if elem.get('type') == 'table':
        content = elem.get('content', '')
        if 'Calendar year 1995' in content:
            lines = content.split('<tr>')
            for line in lines:
                match = re.search(r'<td>([^<]+)</td><td>([0-9,]+)</td>', line)
                if match:
                    country = match.group(1)
                    value_1995 = match.group(2).replace(',', '')
                    if value_1995 and value_1995.isdigit() and int(value_1995) > 0:
                        if country not in all_countries or int(value_1995) > all_countries[country]:
                            all_countries[country] = int(value_1995)

# Exclude obvious non-country entries and find highest
exclude_patterns = ['Total', 'Payable', 'Banks', 'Own', 'Claims', 'IBFs', 'All other', 'Deposits', 'Negotiable', 'Other', 'On ', 'foreign', 'International', 'regional']
exclude_territories = ['British West Indies', 'Bahamas', 'Netherlands Antilles']

print('Individual countries (excluding obvious territories/aggregates):')
for country, value in sorted(all_countries.items(), key=lambda x: -x[1]):
    # Skip if matches exclusion patterns
    skip = False
    for pattern in exclude_patterns:
        if pattern in country:
            skip = True
            break
    for terr in exclude_territories:
        if terr in country:
            skip = True
            break
    if not skip:
        print(f'{country}: {value}')
"
